#!/usr/bin/env python3
import argparse
import json
import os
import subprocess
import sys
from pathlib import Path

import requests

from media_request_common import (
    default_config_path,
    default_output_dir,
    failure_hints,
    load_provider,
    request_exception_hint,
    run_fetch_helper,
)


DEFAULT_PROVIDER = os.environ.get("OPENCLAW_MEDIA_PROVIDER")
DEFAULT_MODEL = os.environ.get("OPENCLAW_MEDIA_EDIT_MODEL", "image-edit-model")
DEFAULT_CONFIG = str(default_config_path())
DEFAULT_OUT_DIR = str(default_output_dir("images"))


def parse_args():
    p = argparse.ArgumentParser(description="Call the configured image-edit model and optionally download the result.")
    p.add_argument("--image", required=True, help="Path to the source image")
    p.add_argument("--prompt", required=True, help="Editing prompt")
    p.add_argument("--mask", help="Optional mask image path for localized edits")
    p.add_argument("--config", default=DEFAULT_CONFIG, help="OpenClaw config path (default: ~/.openclaw/openclaw.json or OPENCLAW_CONFIG env var)")
    p.add_argument("--provider", default=DEFAULT_PROVIDER, help="Provider key inside models.providers (defaults to OPENCLAW_MEDIA_PROVIDER env var or the first provider in config)")
    p.add_argument("--model", default=DEFAULT_MODEL, help="Image edit model id (defaults to OPENCLAW_MEDIA_EDIT_MODEL env var or a placeholder)")
    p.add_argument("--endpoint", default="/images/edits", help="Relative API endpoint")
    p.add_argument("--out-dir", default=DEFAULT_OUT_DIR, help="Directory for downloaded outputs")
    p.add_argument("--prefix", default="edited", help="Output filename prefix")
    p.add_argument("--timeout", type=int, default=180, help="HTTP timeout in seconds")
    p.add_argument("--download", dest="download", action="store_true", help="Download the returned media URL/path")
    p.add_argument("--no-download", dest="download", action="store_false", help="Only print raw response")
    p.set_defaults(download=True)
    p.add_argument("--print-json", action="store_true", help="Print a JSON summary instead of plain text")
    return p.parse_args()


def extract_first_ref(payload):
    if isinstance(payload, dict):
        data = payload.get("data")
        if isinstance(data, list) and data:
            first = data[0]
            if isinstance(first, dict):
                for key in ("url", "b64_json", "path"):
                    if first.get(key):
                        return first[key]
        for key in ("url", "path"):
            if payload.get(key):
                return payload[key]
    return None


def download_media(script_dir: Path, response_text: str, origin: str, out_dir: str, prefix: str):
    return run_fetch_helper(script_dir, response_text, out_dir, prefix, origin=origin)


def main():
    args = parse_args()
    config_path = Path(args.config).expanduser()
    image_path = Path(args.image)
    if not image_path.exists():
        raise SystemExit(f"image not found: {image_path}")
    mask_path = Path(args.mask) if args.mask else None
    if mask_path and not mask_path.exists():
        raise SystemExit(f"mask not found: {mask_path}")

    base_url, api_key, resolved_provider = load_provider(config_path, args.provider)
    url = base_url + args.endpoint
    Path(args.out_dir).mkdir(parents=True, exist_ok=True)

    if args.model == "image-edit-model":
        print("WARN: using placeholder model 'image-edit-model'. Pass --model or set the OPENCLAW_MEDIA_EDIT_MODEL env var for a real provider model name.", file=sys.stderr)

    try:
        with image_path.open("rb") as f:
            files = {"image": (image_path.name, f, "application/octet-stream")}
            if mask_path:
                with mask_path.open("rb") as mf:
                    files["mask"] = (mask_path.name, mf, "image/png")
                    resp = requests.post(url, headers={"Authorization": f"Bearer {api_key}"}, data={"model": args.model, "prompt": args.prompt}, files=files, timeout=args.timeout)
            else:
                resp = requests.post(url, headers={"Authorization": f"Bearer {api_key}"}, data={"model": args.model, "prompt": args.prompt}, files=files, timeout=args.timeout)
    except requests.RequestException as e:
        raise SystemExit(request_exception_hint(e))

    raw_text = resp.text
    summary = {
        "status": resp.status_code,
        "ok": resp.ok,
        "model": args.model,
        "provider": resolved_provider,
        "endpoint": url,
        "mask": str(mask_path) if mask_path else None,
        "response": None,
        "downloaded": None,
        "hints": failure_hints(resp.status_code, args.endpoint, "image editing"),
    }

    parsed = None
    try:
        parsed = resp.json()
        summary["response"] = parsed
    except Exception:
        summary["response"] = raw_text

    if not resp.ok:
        if args.print_json:
            print(json.dumps(summary, ensure_ascii=False, indent=2))
        else:
            print(f"STATUS: {resp.status_code}")
            print(raw_text)
            for hint in summary["hints"]:
                print(f"HINT: {hint}")
        raise SystemExit(1)

    if args.download:
        ref = extract_first_ref(parsed) if parsed is not None else None
        response_text = json.dumps(parsed, ensure_ascii=False) if parsed is not None else raw_text
        origin = base_url if ref and isinstance(ref, str) and ref.startswith("/") else None
        downloaded = download_media(Path(__file__).resolve().parent, response_text, origin, args.out_dir, args.prefix)
        summary["downloaded"] = downloaded

    if args.print_json:
        print(json.dumps(summary, ensure_ascii=False, indent=2))
    else:
        print(f"STATUS: {resp.status_code}")
        if parsed is not None:
            print(json.dumps(parsed, ensure_ascii=False))
        else:
            print(raw_text)
        if summary["downloaded"]:
            print(f"DOWNLOADED: {summary['downloaded']}")


if __name__ == "__main__":
    try:
        main()
    except subprocess.CalledProcessError as e:
        stderr = e.stderr.strip() if e.stderr else str(e)
        print(f"ERROR: download helper failed: {stderr}", file=sys.stderr)
        raise

#!/usr/bin/env python3
import argparse
import base64
import json
import mimetypes
import os
import re
import sys
import uuid
from pathlib import Path
from urllib.parse import urlparse

import requests


def parse_args():
    p = argparse.ArgumentParser(description="Extract a generated media URL/path from model output and download it.")
    src = p.add_mutually_exclusive_group(required=True)
    src.add_argument("--response-text", help="Raw response text containing HTML, markdown, or direct media URLs")
    src.add_argument("--response-file", help="Path to a text file containing the raw response")
    p.add_argument("--origin", help="Prefix to use when the extracted media path is relative")
    p.add_argument("--out-dir", required=True, help="Directory to save the downloaded file into")
    p.add_argument("--prefix", default="generated", help="Output filename prefix")
    p.add_argument("--timeout", type=int, default=600, help="HTTP timeout in seconds")
    p.add_argument("--header", action="append", default=[], help="Extra header in 'Key: Value' format; repeatable")
    return p.parse_args()


def load_text(args):
    if args.response_text is not None:
        return args.response_text
    with open(args.response_file, "r", encoding="utf-8") as f:
        return f.read()


def extract_b64_json(text):
    try:
        payload = json.loads(text)
    except Exception:
        payload = None

    if isinstance(payload, dict):
        data = payload.get("data")
        if isinstance(data, list):
            for item in data:
                if isinstance(item, dict) and item.get("b64_json"):
                    return item["b64_json"]
        if payload.get("b64_json"):
            return payload["b64_json"]

    m = re.search(r'"b64_json"\s*:\s*"([A-Za-z0-9+/=\\n\\r]+)"', text)
    if m:
        return re.sub(r'\s+', '', m.group(1))
    return None


def extract_media_ref(text):
    preferred = [
        r'src=\\?"([^"]+generated_video\.mp4)\\?"',
        r'https?://[^\s"\'\\]+generated_video\.mp4',
        r'!\[video\]\(([^)]+)\)',
        r'!\[image\]\(([^)]+)\)',
        r'data:(image|video)/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+',
    ]
    for pat in preferred:
        m = re.search(pat, text)
        if m:
            ref = m.group(0) if pat.startswith('data:') else (m.group(1) if m.groups() else m.group(0))
            return ref.rstrip('\\').strip()

    fallback = [
        r'https?://[^\s"\'\\]+(?:\.jpg|\.jpeg|\.png|\.webp|\.gif|\.mp4|\.webm|\.mov)(?:\?[^\s"\'\\]*)?',
        r'/v1/files/[^\s"\')<]+',
    ]
    for pat in fallback:
        m = re.search(pat, text)
        if m:
            ref = m.group(1) if m.groups() else m.group(0)
            return ref.rstrip('\\').strip()
    return None


def parse_data_url(ref):
    m = re.match(r'data:([^;,]+);base64,(.+)', ref, re.DOTALL)
    if not m:
        raise SystemExit('invalid data URL')
    return m.group(1).strip().lower(), base64.b64decode(re.sub(r'\s+', '', m.group(2)))


def build_url(ref, origin):
    if ref.startswith('http://') or ref.startswith('https://'):
        return ref.rstrip('\\')
    if ref.startswith('data:'):
        return ref
    if not origin:
        raise SystemExit(f"relative media path found but --origin was not provided: {ref}")
    return origin.rstrip('/') + '/' + ref.lstrip('/')


def parse_headers(header_args):
    headers = {}
    for item in header_args:
        if ':' not in item:
            raise SystemExit(f"invalid --header value: {item}")
        k, v = item.split(':', 1)
        headers[k.strip()] = v.strip()
    return headers


def guess_extension(url, content_type):
    ct = (content_type or '').split(';', 1)[0].strip().lower()
    by_ct = {
        'image/jpeg': '.jpg',
        'image/png': '.png',
        'image/webp': '.webp',
        'image/gif': '.gif',
        'video/mp4': '.mp4',
        'video/webm': '.webm',
        'video/quicktime': '.mov',
    }
    if ct in by_ct:
        return by_ct[ct]
    if url and not url.startswith('data:'):
        ext = os.path.splitext(urlparse(url).path)[1].lower()
        if ext:
            return ext
    return mimetypes.guess_extension(ct) or '.bin'


def save_bytes(out_dir, prefix, ext, content):
    Path(out_dir).mkdir(parents=True, exist_ok=True)
    out_path = Path(out_dir) / f"{prefix}_{uuid.uuid4().hex[:8]}{ext}"
    out_path.write_bytes(content)
    return str(out_path)


def main():
    args = parse_args()
    text = load_text(args)

    b64_json = extract_b64_json(text)
    if b64_json:
        content = base64.b64decode(re.sub(r'\s+', '', b64_json))
        out_path = save_bytes(args.out_dir, args.prefix, '.png', content)
        print(out_path)
        return

    ref = extract_media_ref(text)
    if not ref:
        raise SystemExit('no media reference found in response')

    url = build_url(ref, args.origin)
    if url.startswith('data:'):
        content_type, content = parse_data_url(url)
        ext = guess_extension(url, content_type)
        out_path = save_bytes(args.out_dir, args.prefix, ext, content)
        print(out_path)
        return

    headers = parse_headers(args.header)
    resp = requests.get(url, headers=headers, timeout=args.timeout)
    resp.raise_for_status()

    ext = guess_extension(url, resp.headers.get('content-type'))
    out_path = save_bytes(args.out_dir, args.prefix, ext, resp.content)
    print(out_path)


if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        print(f"ERROR: {e}", file=sys.stderr)
        raise

#!/usr/bin/env python3
import argparse
import json
import subprocess
import sys
from pathlib import Path


SCRIPT_DIR = Path(__file__).resolve().parent


class SafeDict(dict):
    def __missing__(self, key):
        return "{" + key + "}"


def parse_args():
    p = argparse.ArgumentParser(description="Run a batch media manifest through the media-generation helpers.")
    p.add_argument("--manifest", required=True, help="Path to a JSON or JSONL manifest")
    p.add_argument("--vars-json", help="Shared JSON object used for string templating")
    p.add_argument("--vars-file", help="Path to a shared JSON object used for string templating")
    p.add_argument("--summary-out", help="Optional JSON file to write the full batch summary")
    p.add_argument("--continue-on-error", action="store_true", help="Continue processing later items after a failure")
    p.add_argument("--dry-run", action="store_true", help="Print the resolved commands without executing them")
    p.add_argument("--print-json", action="store_true", help="Print structured JSON output")
    return p.parse_args()


def load_json_object(text, label):
    obj = json.loads(text)
    if not isinstance(obj, dict):
        raise SystemExit(f"{label} must decode to a JSON object")
    return obj


def load_manifest(path: Path):
    text = path.read_text(encoding="utf-8")
    stripped = text.strip()
    if not stripped:
        return []
    if stripped.startswith("["):
        items = json.loads(stripped)
        if not isinstance(items, list):
            raise SystemExit("JSON manifest must be an array")
        return items
    items = []
    for idx, line in enumerate(text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except json.JSONDecodeError as e:
            raise SystemExit(f"invalid JSONL at line {idx}: {e}")
        items.append(item)
    return items


def load_shared_vars(args):
    shared = {}
    if args.vars_json:
        shared.update(load_json_object(args.vars_json, "--vars-json"))
    if args.vars_file:
        shared.update(load_json_object(Path(args.vars_file).read_text(encoding="utf-8"), "--vars-file"))
    return shared


def render_value(value, vars_map):
    if isinstance(value, str):
        return value.format_map(SafeDict(vars_map))
    if isinstance(value, list):
        return [render_value(v, vars_map) for v in value]
    if isinstance(value, dict):
        return {k: render_value(v, vars_map) for k, v in value.items() if k != "vars"}
    return value


def render_item(item, shared_vars, index):
    local_vars = item.get("vars") or {}
    if local_vars and not isinstance(local_vars, dict):
        raise SystemExit("manifest item field 'vars' must be an object when present")
    vars_map = dict(shared_vars)
    vars_map.update(local_vars)
    vars_map.setdefault("index", index)
    vars_map.setdefault("mode", item.get("mode", "image"))
    rendered = render_value(item, vars_map)
    rendered["vars"] = vars_map
    return rendered


def choose_script(item):
    mode = item.get("mode", "image")
    if item.get("consistent") or item.get("reference_image") or item.get("reference_images"):
        return SCRIPT_DIR / "generate_consistent_media.py"
    if mode == "video":
        return SCRIPT_DIR / "generate_video.py"
    if mode == "image":
        return SCRIPT_DIR / "generate_image.py"
    raise SystemExit(f"unsupported mode in manifest item: {mode}")


def add_repeatable(cmd, flag, value):
    if value is None:
        return
    if isinstance(value, list):
        for item in value:
            cmd.extend([flag, str(item)])
    else:
        cmd.extend([flag, str(value)])


def item_to_command(item):
    script = choose_script(item)
    prompt = item.get("prompt")
    if not prompt:
        raise SystemExit("manifest item missing required field: prompt")

    cmd = [sys.executable, str(script), "--prompt", str(prompt)]

    if script.name == "generate_consistent_media.py":
        cmd.extend(["--mode", str(item.get("mode", "image"))])
        add_repeatable(cmd, "--reference-image", item.get("reference_images") or item.get("reference_image"))
        if item.get("reference_key"):
            cmd.extend(["--reference-key", str(item["reference_key"])])
        if item.get("transport"):
            cmd.extend(["--transport", str(item["transport"])])

    simple_flags = [
        "provider", "model", "endpoint", "out_dir", "prefix", "size", "quality", "style", "background",
        "n", "seed", "duration", "seconds", "fps", "config", "status_endpoint_template", "image",
        "extra_json", "extra_json_file", "timeout", "poll_interval", "max_polls",
    ]
    for key in simple_flags:
        if key in item and item[key] is not None:
            cmd.extend(["--" + key.replace("_", "-"), str(item[key])])

    if item.get("download") is False:
        cmd.append("--no-download")
    if item.get("print_json"):
        cmd.append("--print-json")
    return cmd


def maybe_write_summary(path, summary):
    if not path:
        return
    out_path = Path(path)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")


def main():
    args = parse_args()
    items = load_manifest(Path(args.manifest))
    shared_vars = load_shared_vars(args)
    results = []
    overall_ok = True

    for index, raw_item in enumerate(items, start=1):
        item = render_item(raw_item, shared_vars, index)
        cmd = item_to_command(item)
        record = {"index": index, "item": item, "cmd": cmd, "ok": None, "stdout": None, "stderr": None}
        if args.dry_run:
            record["ok"] = True
            results.append(record)
            continue
        proc = subprocess.run(cmd, text=True, capture_output=True)
        record["ok"] = proc.returncode == 0
        record["stdout"] = proc.stdout.strip()
        record["stderr"] = proc.stderr.strip()
        results.append(record)
        if proc.returncode != 0:
            overall_ok = False
            if not args.continue_on_error:
                break

    summary = {
        "ok": overall_ok,
        "count": len(items),
        "manifest": args.manifest,
        "summary_out": args.summary_out,
        "results": results,
    }
    maybe_write_summary(args.summary_out, summary)
    if args.print_json or args.dry_run:
        print(json.dumps(summary, ensure_ascii=False, indent=2))
    else:
        for item in results:
            print(json.dumps(item, ensure_ascii=False))
    if not overall_ok:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import base64
import json
import mimetypes
import os
import subprocess
import sys
import time
from pathlib import Path

import requests

from media_request_common import (
    default_config_path,
    default_output_dir,
    failure_hints,
    load_provider,
    merge_extra_json,
    request_exception_hint,
    run_fetch_helper,
)


DEFAULT_PROVIDER = os.environ.get("OPENCLAW_MEDIA_PROVIDER")
DEFAULT_MODEL = os.environ.get("OPENCLAW_MEDIA_VIDEO_MODEL", "video-model")
DEFAULT_CONFIG = str(default_config_path())
DEFAULT_OUT_DIR = str(default_output_dir("videos"))
DEFAULT_HEADERS = ["User-Agent: Mozilla/5.0"]


def parse_args():
    p = argparse.ArgumentParser(description="Call the configured video-generation model, poll if needed, and optionally download the result.")
    p.add_argument("--prompt", required=True, help="Request prompt")
    p.add_argument("--config", default=DEFAULT_CONFIG, help="OpenClaw config path (default: ~/.openclaw/openclaw.json or OPENCLAW_CONFIG env var)")
    p.add_argument("--provider", default=DEFAULT_PROVIDER, help="Provider key inside models.providers (defaults to OPENCLAW_MEDIA_PROVIDER env var or the first provider in config)")
    p.add_argument("--model", default=DEFAULT_MODEL, help="Video generation model id (defaults to OPENCLAW_MEDIA_VIDEO_MODEL env var or a placeholder)")
    p.add_argument("--endpoint", default="/videos", help="Relative API endpoint")
    p.add_argument("--status-endpoint-template", default="/videos/{id}", help="Relative poll endpoint template when only an id is returned")
    p.add_argument("--out-dir", default=DEFAULT_OUT_DIR, help="Directory for downloaded outputs")
    p.add_argument("--prefix", default="generated-video", help="Output filename prefix")
    p.add_argument("--size", help="Optional size, e.g. 720x1280")
    p.add_argument("--duration", help="Optional duration, e.g. 5s or 6")
    p.add_argument("--seconds", type=int, help="Optional duration in whole seconds; overrides --duration normalization when provided")
    p.add_argument("--fps", type=int, help="Optional target fps")
    p.add_argument("--seed", type=int, help="Optional random seed if supported by provider")
    p.add_argument("--image", help="Optional input image path when supported by provider")
    p.add_argument("--mode", choices=["text", "animate", "reference"], default="text", help="Request mode")
    p.add_argument("--image-transport", choices=["auto", "path", "data-url"], default="auto", help="How to serialize --image into JSON")
    p.add_argument("--image-field", choices=["image", "input_image", "first_frame_image", "reference_images"], help="Provider JSON field for the image input")
    p.add_argument("--extra-json", help="Extra JSON object merged into the request body")
    p.add_argument("--extra-json-file", help="Path to a JSON file merged into the request body")
    p.add_argument("--timeout", type=int, default=600, help="HTTP timeout in seconds")
    p.add_argument("--poll-interval", type=float, default=5.0, help="Seconds between poll attempts")
    p.add_argument("--max-polls", type=int, default=60, help="Maximum poll attempts when the job is asynchronous")
    p.add_argument("--download", dest="download", action="store_true", help="Download the returned media URL/path")
    p.add_argument("--no-download", dest="download", action="store_false", help="Only print raw response")
    p.set_defaults(download=True)
    p.add_argument("--print-json", action="store_true", help="Print a JSON summary instead of plain text")
    return p.parse_args()


def normalize_seconds(duration_text):
    if duration_text is None:
        return None
    text = str(duration_text).strip().lower()
    if text.endswith("s"):
        text = text[:-1].strip()
    if not text:
        return None
    try:
        value = int(float(text))
    except ValueError:
        raise SystemExit(f"invalid --duration value: {duration_text}")
    if value <= 0:
        raise SystemExit("duration/seconds must be positive")
    return value


def choose_image_field(args):
    if args.image_field:
        return args.image_field
    if args.mode == "animate":
        return "first_frame_image"
    if args.mode == "reference":
        return "reference_images"
    return "image"


def choose_image_transport(args):
    if args.image_transport != "auto":
        return args.image_transport
    if args.mode in {"animate", "reference"}:
        return "data-url"
    return "path"


def image_to_data_url(image_path: Path):
    mime = mimetypes.guess_type(image_path.name)[0] or "application/octet-stream"
    return f"data:{mime};base64," + base64.b64encode(image_path.read_bytes()).decode("ascii")


def normalize_image_value(image_path: Path, transport: str):
    if transport == "path":
        return str(image_path)
    if transport == "data-url":
        return image_to_data_url(image_path)
    raise SystemExit(f"unsupported image transport: {transport}")


def build_payload(args):
    prompt = args.prompt.strip()
    payload = {"model": args.model, "prompt": prompt}
    seconds = args.seconds if args.seconds is not None else normalize_seconds(args.duration)
    optional = {"size": args.size, "seconds": seconds, "fps": args.fps, "seed": args.seed}
    for key, value in optional.items():
        if value is not None:
            payload[key] = value

    image_meta = {"provided": False, "field": None, "transport": None, "path": None}
    if args.image:
        image_path = Path(args.image)
        if not image_path.exists():
            raise SystemExit(f"image not found: {image_path}")
        image_field = choose_image_field(args)
        image_transport = choose_image_transport(args)
        image_value = normalize_image_value(image_path, image_transport)
        if image_field == "reference_images":
            payload[image_field] = [image_value]
        else:
            payload[image_field] = image_value
        image_meta = {
            "provided": True,
            "field": image_field,
            "transport": image_transport,
            "path": str(image_path),
        }
    elif args.mode != "text":
        raise SystemExit(f"--mode {args.mode} requires --image")

    payload = merge_extra_json(payload, args.extra_json, args.extra_json_file)
    return payload, image_meta, prompt


def find_first_value(obj, keys):
    if isinstance(obj, dict):
        for key in keys:
            if key in obj and obj[key] not in (None, ""):
                return obj[key]
        for value in obj.values():
            found = find_first_value(value, keys)
            if found not in (None, ""):
                return found
    elif isinstance(obj, list):
        for item in obj:
            found = find_first_value(item, keys)
            if found not in (None, ""):
                return found
    return None


def has_media_ref(obj):
    return find_first_value(obj, {"url", "path", "video_url", "result_url", "output_url", "b64_json"})


def extract_job_id(obj):
    for key in ("id", "job_id", "task_id", "request_id", "prediction_id"):
        found = find_first_value(obj, {key})
        if found:
            return found
    return None


def extract_status_url(obj):
    return find_first_value(obj, {"status_url", "poll_url", "result_url", "retrieve_url"})


def extract_status_text(obj):
    return find_first_value(obj, {"status", "state"})


def poll_until_ready(base_url, api_key, initial_payload, endpoint_template, interval, max_polls, timeout):
    payload = initial_payload
    if has_media_ref(payload):
        return payload
    status_url = extract_status_url(payload)
    job_id = extract_job_id(payload)
    if not status_url and job_id:
        status_url = base_url + endpoint_template.format(id=job_id)
    if not status_url:
        return payload
    if status_url.startswith("/"):
        status_url = base_url + status_url
    headers = {"Authorization": f"Bearer {api_key}", "Accept": "application/json"}
    last_payload = payload
    for _ in range(max_polls):
        try:
            resp = requests.get(status_url, headers=headers, timeout=timeout)
        except requests.RequestException as e:
            raise SystemExit(request_exception_hint(e))
        text = resp.text
        try:
            polled = resp.json()
        except Exception:
            polled = {"raw": text}
        last_payload = polled
        if has_media_ref(polled):
            return polled
        status = str(extract_status_text(polled) or "").lower()
        if status in {"failed", "error", "cancelled", "canceled"}:
            return polled
        time.sleep(interval)
    return last_payload


def redact_request_for_summary(payload):
    def _redact(value):
        if isinstance(value, dict):
            redacted = {}
            for k, v in value.items():
                if k in {"image", "input_image", "first_frame_image"} and isinstance(v, str) and v.startswith("data:"):
                    redacted[k] = "data:..."
                elif k == "reference_images" and isinstance(v, list):
                    redacted[k] = ["data:..." if isinstance(item, str) and item.startswith("data:") else item for item in v]
                else:
                    redacted[k] = _redact(v)
            return redacted
        if isinstance(value, list):
            return [_redact(item) for item in value]
        return value

    return _redact(payload)


def main():
    args = parse_args()
    config_path = Path(args.config).expanduser()
    base_url, api_key, resolved_provider = load_provider(config_path, args.provider)
    url = base_url + args.endpoint
    Path(args.out_dir).mkdir(parents=True, exist_ok=True)

    payload, image_meta, final_prompt = build_payload(args)
    if args.model == "video-model":
        print("WARN: using placeholder model 'video-model'. Pass --model or set the OPENCLAW_MEDIA_VIDEO_MODEL env var for a real provider model name.", file=sys.stderr)
    try:
        resp = requests.post(
            url,
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json", "Accept": "application/json"},
            json=payload,
            timeout=args.timeout,
        )
    except requests.RequestException as e:
        raise SystemExit(request_exception_hint(e))

    raw_text = resp.text
    try:
        parsed = resp.json()
    except Exception:
        parsed = {"raw": raw_text}

    summary = {
        "status": resp.status_code,
        "ok": resp.ok,
        "model": args.model,
        "provider": resolved_provider,
        "endpoint": url,
        "mode": args.mode,
        "image": image_meta,
        "prompt": final_prompt,
        "request": redact_request_for_summary(payload),
        "response": parsed,
        "resolved": None,
        "downloaded": None,
        "hints": failure_hints(resp.status_code, args.endpoint, "video generation"),
    }

    if not resp.ok:
        if args.print_json:
            print(json.dumps(summary, ensure_ascii=False, indent=2))
        else:
            print(f"STATUS: {resp.status_code}")
            print(raw_text)
            for hint in summary["hints"]:
                print(f"HINT: {hint}")
        raise SystemExit(1)

    resolved = poll_until_ready(base_url, api_key, parsed, args.status_endpoint_template, args.poll_interval, args.max_polls, args.timeout)
    summary["resolved"] = resolved
    status = str(extract_status_text(resolved) or "").lower()
    if status in {"failed", "error", "cancelled", "canceled"}:
        if args.print_json:
            print(json.dumps(summary, ensure_ascii=False, indent=2))
        else:
            print(json.dumps(summary, ensure_ascii=False))
            print("HINT: the provider accepted the request but the async job finished in a failed state")
        raise SystemExit(1)

    if args.download:
        ref = has_media_ref(resolved)
        response_text = json.dumps(resolved, ensure_ascii=False)
        origin = base_url if isinstance(ref, str) and ref.startswith("/") else None
        if ref:
            downloaded = run_fetch_helper(Path(__file__).resolve().parent, response_text, args.out_dir, args.prefix, origin=origin, headers=DEFAULT_HEADERS)
            summary["downloaded"] = downloaded

    if args.print_json:
        print(json.dumps(summary, ensure_ascii=False, indent=2))
    else:
        print(f"STATUS: {resp.status_code}")
        print(json.dumps(summary, ensure_ascii=False))
        if summary["downloaded"]:
            print(f"DOWNLOADED: {summary['downloaded']}")


if __name__ == "__main__":
    try:
        main()
    except subprocess.CalledProcessError as e:
        stderr = e.stderr.strip() if e.stderr else str(e)
        print(f"ERROR: download helper failed: {stderr}", file=sys.stderr)
        raise

#!/usr/bin/env python3
import argparse
import subprocess
import sys
import uuid
from pathlib import Path

from PIL import Image, ImageDraw, ImageFilter

from media_request_common import default_mask_dir, default_output_dir


DEFAULT_MASK_DIR = str(default_mask_dir())
DEFAULT_OUT_DIR = str(default_output_dir("images"))


def parse_args():
    p = argparse.ArgumentParser(description="Create or reuse a mask image and call the image-edit helper.")
    p.add_argument("--image", required=True, help="Path to the source image")
    p.add_argument("--prompt", required=True, help="Edit request text")
    p.add_argument("--mask", help="Optional existing mask image path")
    p.add_argument("--mask-dir", default=DEFAULT_MASK_DIR, help="Directory for generated masks")
    p.add_argument("--out-dir", default=DEFAULT_OUT_DIR, help="Directory for final edited outputs")
    p.add_argument("--prefix", default="inpaint", help="Filename prefix")
    p.add_argument("--config", help="Forwarded config path for edit_image.py")
    p.add_argument("--provider", help="Forwarded provider for edit_image.py")
    p.add_argument("--model", help="Forwarded image edit model for edit_image.py")
    p.add_argument("--endpoint", help="Forwarded endpoint for edit_image.py")
    p.add_argument("--x", type=int, help="Rectangle left")
    p.add_argument("--y", type=int, help="Rectangle top")
    p.add_argument("--width", type=int, help="Rectangle width")
    p.add_argument("--height", type=int, help="Rectangle height")
    p.add_argument("--x2", type=int, help="Rectangle right")
    p.add_argument("--y2", type=int, help="Rectangle bottom")
    p.add_argument("--ellipse", action="store_true", help="Use an ellipse for the legacy single-region coordinates instead of a rectangle")
    p.add_argument("--region", action="append", default=[], help="Repeatable region spec. Formats: rect:x:y:w:h, box:x1:y1:x2:y2, ellipse:x:y:w:h, rect-pct:x:y:w:h, box-pct:x1:y1:x2:y2, ellipse-pct:x:y:w:h")
    p.add_argument("--feather", type=int, default=8, help="Mask feather radius in pixels")
    p.add_argument("--expand", type=int, default=0, help="Grow the mask by this many pixels before feathering")
    p.add_argument("--shrink", type=int, default=0, help="Shrink the mask by this many pixels before feathering")
    p.add_argument("--invert", action="store_true", help="Invert the generated or supplied mask before use")
    p.add_argument("--mask-only", action="store_true", help="Only generate and save the mask, then exit")
    p.add_argument("--print-json", action="store_true", help="Forward --print-json to edit_image.py")
    p.add_argument("--no-download", action="store_true", help="Forward --no-download to edit_image.py")
    return p.parse_args()


def clamp(n, lo, hi):
    return max(lo, min(hi, n))


def odd_kernel(px):
    value = max(1, int(px) * 2 + 1)
    return value if value % 2 == 1 else value + 1


def apply_expand_shrink(mask, expand, shrink):
    if expand > 0:
        mask = mask.filter(ImageFilter.MaxFilter(size=odd_kernel(expand)))
    if shrink > 0:
        mask = mask.filter(ImageFilter.MinFilter(size=odd_kernel(shrink)))
    return mask


def parse_float_list(text, expected):
    parts = [p.strip() for p in text.split(":")]
    if len(parts) != expected:
        raise SystemExit(f"invalid region spec: {text}")
    try:
        return [float(p) for p in parts]
    except ValueError:
        raise SystemExit(f"invalid numeric region spec: {text}")


def normalize_region(kind, numbers, w, h):
    pct = kind.endswith("-pct")
    base_kind = kind[:-4] if pct else kind
    if pct:
        if base_kind in {"rect", "ellipse"}:
            x, y, rw, rh = numbers
            x1 = round(w * x / 100.0)
            y1 = round(h * y / 100.0)
            x2 = round(w * (x + rw) / 100.0)
            y2 = round(h * (y + rh) / 100.0)
        elif base_kind == "box":
            x1, y1, x2, y2 = [round(v * axis / 100.0) for v, axis in zip(numbers, (w, h, w, h))]
        else:
            raise SystemExit(f"unsupported region kind: {kind}")
    else:
        if base_kind in {"rect", "ellipse"}:
            x, y, rw, rh = numbers
            x1 = round(x)
            y1 = round(y)
            x2 = round(x + rw)
            y2 = round(y + rh)
        elif base_kind == "box":
            x1, y1, x2, y2 = [round(v) for v in numbers]
        else:
            raise SystemExit(f"unsupported region kind: {kind}")
    x1 = clamp(x1, 0, w)
    y1 = clamp(y1, 0, h)
    x2 = clamp(x2, 0, w)
    y2 = clamp(y2, 0, h)
    if x2 <= x1 or y2 <= y1:
        raise SystemExit(f"invalid region after clamping: {kind}:{numbers}")
    return base_kind, (x1, y1, x2, y2)


def collect_regions(args, w, h):
    regions = []
    if None not in (args.x, args.y, args.width, args.height):
        kind = "ellipse" if args.ellipse else "rect"
        regions.append((kind, normalize_region(kind, [args.x, args.y, args.width, args.height], w, h)[1]))
    elif None not in (args.x, args.y, args.x2, args.y2):
        if args.ellipse:
            regions.append(("ellipse", normalize_region("ellipse", [args.x, args.y, args.x2 - args.x, args.y2 - args.y], w, h)[1]))
        else:
            regions.append(("box", normalize_region("box", [args.x, args.y, args.x2, args.y2], w, h)[1]))
    for spec in args.region:
        try:
            kind, coords = spec.split(":", 1)
        except ValueError:
            raise SystemExit(f"invalid --region format: {spec}")
        normalized = normalize_region(kind, parse_float_list(coords, 4), w, h)
        regions.append((normalized[0], normalized[1]))
    if not regions and not args.mask:
        raise SystemExit("provide either --mask, a legacy single region, or one or more --region specs")
    return regions


def draw_regions(mask, regions):
    draw = ImageDraw.Draw(mask)
    for kind, box in regions:
        if kind in {"rect", "box"}:
            draw.rectangle(box, fill=255)
        elif kind == "ellipse":
            draw.ellipse(box, fill=255)
        else:
            raise SystemExit(f"unsupported region draw kind: {kind}")
    return mask


def load_existing_mask(image_path: Path, mask_path: Path, invert: bool):
    if not mask_path.exists():
        raise SystemExit(f"mask not found: {mask_path}")
    with Image.open(image_path) as src:
        size = src.size
    with Image.open(mask_path) as m:
        mask = m.convert("L")
        if mask.size != size:
            mask = mask.resize(size)
        if invert:
            mask = Image.eval(mask, lambda px: 255 - px)
    return mask


def save_mask(mask, mask_dir: Path, prefix: str):
    out = mask_dir / f"{prefix}_mask_{uuid.uuid4().hex[:8]}.png"
    out.parent.mkdir(parents=True, exist_ok=True)
    mask.save(out)
    return out


def prepare_mask(image_path: Path, args):
    mask_dir = Path(args.mask_dir)
    if args.mask:
        mask = load_existing_mask(image_path, Path(args.mask), args.invert)
        mask = apply_expand_shrink(mask, args.expand, args.shrink)
        if args.feather > 0:
            mask = mask.filter(ImageFilter.GaussianBlur(radius=args.feather))
        return save_mask(mask, mask_dir, args.prefix)
    with Image.open(image_path) as src:
        w, h = src.size
    regions = collect_regions(args, w, h)
    mask = Image.new("L", (w, h), 0)
    draw_regions(mask, regions)
    mask = apply_expand_shrink(mask, args.expand, args.shrink)
    if args.feather > 0:
        mask = mask.filter(ImageFilter.GaussianBlur(radius=args.feather))
    if args.invert:
        mask = Image.eval(mask, lambda px: 255 - px)
    return save_mask(mask, mask_dir, args.prefix)


def main():
    args = parse_args()
    image_path = Path(args.image)
    if not image_path.exists():
        raise SystemExit(f"image not found: {image_path}")
    mask_path = prepare_mask(image_path, args)
    if args.mask_only:
        print(mask_path)
        return
    edit_script = Path(__file__).resolve().parent / "edit_image.py"
    cmd = [sys.executable, str(edit_script), "--image", str(image_path), "--mask", str(mask_path), "--prompt", args.prompt, "--out-dir", args.out_dir, "--prefix", args.prefix]
    if args.config:
        cmd.extend(["--config", args.config])
    if args.provider:
        cmd.extend(["--provider", args.provider])
    if args.model:
        cmd.extend(["--model", args.model])
    if args.endpoint:
        cmd.extend(["--endpoint", args.endpoint])
    if args.no_download:
        cmd.append("--no-download")
    if args.print_json:
        cmd.append("--print-json")
    result = subprocess.run(cmd, text=True, capture_output=True)
    if result.stdout:
        print(result.stdout, end="")
    if result.returncode != 0:
        if result.stderr:
            print(result.stderr, file=sys.stderr, end="")
        raise SystemExit(result.returncode)
    if not args.print_json:
        print(f"MASK_USED: {mask_path}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import os
import subprocess
import sys
from pathlib import Path


def default_config_path():
    return Path(os.environ.get("OPENCLAW_CONFIG", Path.home() / ".openclaw" / "openclaw.json"))


def default_output_dir(kind: str):
    base = Path(os.environ.get("MEDIA_GENERATION_OUTPUT_ROOT", "tmp"))
    return base / kind


def default_mask_dir():
    return default_output_dir("images") / "masks"


def default_outpaint_work_dir():
    return default_output_dir("images") / "outpaint_inputs"


def load_config(config_path: Path):
    config_path = Path(config_path).expanduser()
    if not config_path.exists():
        raise SystemExit(
            "config not found: "
            f"{config_path}\n"
            "Pass --config explicitly or set the OPENCLAW_CONFIG env var. Expected an OpenClaw config with models.providers entries."
        )
    try:
        return json.loads(config_path.read_text()), config_path
    except json.JSONDecodeError as e:
        raise SystemExit(f"invalid JSON in config {config_path}: {e}")


def load_provider(config_path: Path, provider_name: str | None):
    data, resolved_config_path = load_config(config_path)
    providers = data.get("models", {}).get("providers")
    if not isinstance(providers, dict) or not providers:
        raise SystemExit(
            f"no providers found in config: {resolved_config_path}\n"
            "Expected config.models.providers to be a non-empty object."
        )
    if not provider_name:
        provider_name = sorted(providers.keys())[0]
    if provider_name not in providers:
        available = ", ".join(sorted(providers.keys()))
        raise SystemExit(
            f"provider not found: {provider_name}\n"
            f"Config: {resolved_config_path}\n"
            f"Available providers: {available}\n"
            "Pass --provider with one of the available names, or set the OPENCLAW_MEDIA_PROVIDER env var."
        )
    provider = providers[provider_name]
    if not isinstance(provider, dict):
        raise SystemExit(f"provider entry is not an object: {provider_name}")
    missing = [key for key in ("baseUrl", "apiKey") if not provider.get(key)]
    if missing:
        raise SystemExit(
            f"provider is missing required fields: {provider_name} -> {', '.join(missing)}\n"
            "Expected at least baseUrl and apiKey in config.models.providers.<provider>."
        )
    return provider["baseUrl"].rstrip("/"), provider["apiKey"], provider_name


def merge_extra_json(payload: dict, extra_json=None, extra_json_file=None):
    merged = dict(payload)
    if extra_json:
        try:
            extra = json.loads(extra_json)
        except json.JSONDecodeError as e:
            raise SystemExit(f"invalid --extra-json: {e}")
        if not isinstance(extra, dict):
            raise SystemExit("--extra-json must decode to a JSON object")
        merged.update(extra)
    if extra_json_file:
        extra_path = Path(extra_json_file)
        if not extra_path.exists():
            raise SystemExit(f"--extra-json-file not found: {extra_path}")
        try:
            extra = json.loads(extra_path.read_text())
        except json.JSONDecodeError as e:
            raise SystemExit(f"invalid JSON in --extra-json-file {extra_path}: {e}")
        if not isinstance(extra, dict):
            raise SystemExit("--extra-json-file must contain a JSON object")
        merged.update(extra)
    return merged


def extract_first_ref(payload):
    if isinstance(payload, dict):
        data = payload.get("data")
        if isinstance(data, list):
            for item in data:
                if isinstance(item, dict):
                    for key in ("url", "path", "b64_json"):
                        if item.get(key):
                            return item[key]
        for key in ("url", "path", "b64_json"):
            if payload.get(key):
                return payload[key]
    return None


def failure_hints(status_code, endpoint, modality):
    hints = []
    if status_code in (401, 403):
        hints.append("check apiKey / auth for the selected provider")
    if status_code == 404:
        hints.append(f"check whether the provider exposes {endpoint} for {modality}")
    if status_code == 400:
        hints.append("check provider-specific payload fields, model name, and extra-json contents")
    if status_code == 415:
        hints.append("check content type expectations for this endpoint")
    if status_code >= 500:
        hints.append("provider-side error; retry later or switch provider/model")
    return hints


def request_exception_hint(exc):
    return (
        f"request failed: {exc}\n"
        "Check baseUrl reachability, endpoint path, network connectivity, and TLS/proxy settings for the selected provider."
    )


def run_fetch_helper(script_dir: Path, response_text: str, out_dir: str, prefix: str, origin: str = None, headers=None):
    helper = script_dir / "fetch_generated_media.py"
    cmd = [
        sys.executable,
        str(helper),
        "--response-text",
        response_text,
        "--out-dir",
        out_dir,
        "--prefix",
        prefix,
    ]
    if origin:
        cmd.extend(["--origin", origin])
    for header in headers or []:
        cmd.extend(["--header", header])
    result = subprocess.run(cmd, capture_output=True, text=True, check=True)
    lines = [line for line in result.stdout.strip().splitlines() if line.strip()]
    return lines[-1] if lines else None

#!/usr/bin/env python3
import argparse
import sys
from pathlib import Path

from PIL import Image, ImageChops, ImageFilter


def parse_args():
    p = argparse.ArgumentParser(description="Prepare a practical object/background mask from alpha or simple corner-background separation.")
    p.add_argument("--image", required=True, help="Source image path")
    p.add_argument("--mode", choices=["alpha", "corner-bg"], default="corner-bg", help="Mask derivation mode")
    p.add_argument("--threshold", type=int, default=40, help="Difference threshold for corner-bg mode or alpha threshold for alpha mode")
    p.add_argument("--sample-size", type=int, default=8, help="Corner sample square size for corner-bg mode")
    p.add_argument("--invert", action="store_true", help="Invert the generated mask")
    p.add_argument("--expand", type=int, default=0, help="Expand the white mask region before feathering")
    p.add_argument("--shrink", type=int, default=0, help="Shrink the white mask region before feathering")
    p.add_argument("--feather", type=float, default=4.0, help="Gaussian blur radius for soft edges")
    p.add_argument("--out", help="Output mask path")
    return p.parse_args()


def average_rgb(values):
    count = max(len(values), 1)
    return tuple(int(sum(channel[i] for channel in values) / count) for i in range(3))


def build_corner_bg_mask(img: Image.Image, threshold: int, sample_size: int):
    rgb = img.convert("RGB")
    w, h = rgb.size
    s = max(1, min(sample_size, w, h))
    corners = [
        rgb.crop((0, 0, s, s)),
        rgb.crop((w - s, 0, w, s)),
        rgb.crop((0, h - s, s, h)),
        rgb.crop((w - s, h - s, w, h)),
    ]
    samples = []
    for corner in corners:
        samples.extend(list(corner.getdata()))
    bg = average_rgb(samples)

    out = Image.new("L", rgb.size, 0)
    src = rgb.load()
    dst = out.load()
    for y in range(h):
        for x in range(w):
            r, g, b = src[x, y]
            dist = ((r - bg[0]) ** 2 + (g - bg[1]) ** 2 + (b - bg[2]) ** 2) ** 0.5
            dst[x, y] = 255 if dist >= threshold else 0
    return out


def build_alpha_mask(img: Image.Image, threshold: int):
    rgba = img.convert("RGBA")
    alpha = rgba.getchannel("A")
    return alpha.point(lambda v: 255 if v >= threshold else 0)


def apply_grow_shrink(mask: Image.Image, expand: int, shrink: int):
    result = mask
    if expand > 0:
        result = result.filter(ImageFilter.MaxFilter(size=expand * 2 + 1))
    if shrink > 0:
        result = result.filter(ImageFilter.MinFilter(size=shrink * 2 + 1))
    return result


def main():
    args = parse_args()
    path = Path(args.image)
    if not path.exists():
        raise SystemExit(f"image not found: {path}")
    img = Image.open(path)

    if args.mode == "alpha":
        mask = build_alpha_mask(img, args.threshold)
        if img.mode != "RGBA" and "A" not in img.getbands():
            print("WARN: alpha mode was requested but the source image has no alpha channel; the result may be fully empty or fully solid.", file=sys.stderr)
    else:
        mask = build_corner_bg_mask(img, args.threshold, args.sample_size)

    mask = apply_grow_shrink(mask, args.expand, args.shrink)
    if args.feather > 0:
        mask = mask.filter(ImageFilter.GaussianBlur(radius=args.feather))
    if args.invert:
        mask = ImageChops.invert(mask)

    out_path = Path(args.out) if args.out else path.with_name(path.stem + "_object_mask.png")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    mask.save(out_path)
    print(str(out_path))


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        sys.exit(1)
